package com.weeklyplan.partner;
import java.time.LocalDate; import java.time.Instant; import java.util.Set;
public record PartnerResourceResponse(String id, String name, String website, String region, String introduction, String cooperationStatus, String ownerName, LocalDate nextFollowUpDate, boolean preferred, String riskNote, Integer technicalScore, Integer commercialScore, Integer deliveryScore, Set<String> roles, Set<String> tags, Instant createdAt) { static PartnerResourceResponse of(PartnerResource p) { String owner=p.getOwner().getDisplayName(); return new PartnerResourceResponse(String.valueOf(p.getId()),p.getName(),p.getWebsite(),p.getRegion(),p.getIntroduction(),p.getCooperationStatus(),owner==null||owner.isBlank()?p.getOwner().getUsername():owner,p.getNextFollowUpDate(),p.isPreferred(),p.getRiskNote(),p.getTechnicalScore(),p.getCommercialScore(),p.getDeliveryScore(),p.getRoles(),p.getTags(),p.getCreatedAt()); } }
